 :global(body){margin:0;background:#f5f4ef;color:#20382e;font-family:Inter,Arial,sans-serif;font-size:15px} :global(*){box-sizing:border-box} :global(button),:global(input),:global(select),:global(textarea){font:inherit} :global(button),:global(a){-webkit-tap-highlight-color:transparent}button{cursor:pointer;border:1px solid #c5cec4;background:#fff;color:#20382e;padding:10px 14px;border-radius:7px;white-space:nowrap}button:hover{background:#e8ede4}button:disabled{opacity:.5;cursor:wait}.primary{background:#244d3b;color:white;border-color:#244d3b}.primary:hover{background:#173b2b}a{color:#315e43}header{max-width:1280px;margin:auto;height:84px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d8ded4}.brand{font-size:17px;font-weight:800;text-decoration:none;letter-spacing:2px}.brand span{color:#8b958b;font-size:11px;letter-spacing:1px}nav,.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}nav>a{font-size:13px;margin-right:18px}main{max-width:1200px;margin:auto;padding:0 0 60px}.hero{display:flex;justify-content:space-between;align-items:center;padding:65px 0 48px;gap:30px}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;color:#6a7869}h1{font-size:clamp(34px,4.5vw,60px);font-weight:500;letter-spacing:-2px;margin:20px 0}.intro{color:#718071;font-size:17px;line-height:1.7}.event{border:1px solid #bac7b5;padding:26px 30px;width:266px;transform:rotate(-2deg);background:#e8eddf}.event>span{font-size:11px;letter-spacing:3px}.event strong{display:block;font-size:21px;line-height:1.4;margin:12px 0}.event>div{font-size:44px;font-weight:700;border-top:1px solid #bac7b5;padding-top:10px}.event div span{font-size:12px;letter-spacing:3px;margin-left:15px}.stats{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid #d8ded4;padding:22px 0;gap:20px}.stats>div{display:flex;gap:13px;align-items:center}.stats strong{font-size:29px;font-weight:500}.stats span{font-size:12px;color:#758171}.tabs{di